command:
$ErrorActionPreference = 'Stop'
$buildDirectory = 'D:\GitHub\Forge-Conductor-Windows-Edition\out\build\windows-msvc-x64'
$testPattern = '^(ForgeConductor\.Manager\.StartupTests|ForgeConductor\.Manager\.WindowsInfrastructureTests|ForgeConductor\.Manager\.StartupLifecycleIntegrationTests|ForgeConductor\.Infrastructure\.ProcessTests|ForgeConductor\.Infrastructure\.HeaderSelfContainment)$'
& ctest --test-dir $buildDirectory -C Debug --output-on-failure -R $testPattern
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$tasks = @(Get-ScheduledTask -ErrorAction Stop | Where-Object {
    $_.TaskPath -eq '\' -and
    $_.TaskName -like 'ForgeConductor.Manager.v1.*.p16-lifecycle-integration'
})
if ($tasks.Count -ne 0) {
    throw "Lifecycle test left $($tasks.Count) scheduled task(s)."
}
$tempRoot = [IO.Path]::GetTempPath()
$homes = @(Get-ChildItem -LiteralPath $tempRoot -Directory -Force -Filter 'ForgeConductor.Manager.StartupLifecycle.*' -ErrorAction Stop)
if ($homes.Count -ne 0) {
    throw "Lifecycle test left $($homes.Count) temporary home(s)."
}
Write-Output "LIFECYCLE_TASK_COUNT=$($tasks.Count)"
Write-Output "LIFECYCLE_HOME_COUNT=$($homes.Count)"
exit 0
